arguments.command:
cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo "before fix rc=$?"
sed -i 's|(\$1 \* 90 + 99) / 100|$1 * 90 / 100|' bin/price lib/invoice.sh
bash scripts/verify.sh; echo "after fix rc=$?"
sed -i 's/^- 残り.*/- 完了: bin\/price と lib\/invoice.sh も切り捨てに修正（前メモの invoice 済みは誤りで、実際は未修正だった）。テスト追加済み/' notes/PRC-601.md
git add -A && git commit -q -m "PRC-601: round member price and invoice down, add tests

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>" && git log --oneline -1

